// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon, DicesIcon, SaveIcon, XIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, DEFAULT_TAB, LENGTH, MAX, MIN, ROLLS, TABS } from './script'

const SPARKS = '7a3F9x0Q2k5Z8m1B'.split('')
const INK = '#f5f5f7'
const DIM = 'rgba(245,245,247,0.5)'

const build: Build = ({ tl, q, qa, pos, step, final, move, click, scramble, wait, cursorOut }) => {
  const tabs = pos('tabs', 0, 0)
  const tabAt = (index: number) => {
    const tab = pos(`tab-${index}`, 0, 0)
    return { left: tab.x - tabs.x, width: tab.w }
  }
  let current = DEFAULT_TAB
  tl.set(q('tab-pill'), tabAt(DEFAULT_TAB), 0)

  const select = (index: number) => {
    move(`tab-${index}`)
    click(`tab-${index}`)
    tl.to(q('tab-pill'), { ...tabAt(index), duration: 0.35, ease: 'power3.inOut' }, '<')
    tl.to(q(`tab-${current}`), { color: DIM, duration: 0.2 }, '<')
    tl.to(q(`tab-${index}`), { color: INK, duration: 0.2 }, '<')
    const kind = TABS[index]
    tl.to(q('range'), { opacity: kind === 'Number' ? 1 : 0, duration: 0.2 }, '<')
    tl.to(
      q('length'),
      { opacity: kind === 'Number' || kind === 'UUID' ? 0 : 1, duration: 0.2 },
      '<',
    )
    current = index
  }

  const roll = (index: number) => {
    const { value, chars } = ROLLS[index]
    move('generate')
    click('generate')
    tl.to(q('dice'), { rotation: '+=540', duration: 0.7, ease: 'power3.out' }, '<')
    const origin = pos('generate', 0.2, 0.5)
    const burst = tl.duration()
    qa('spark').forEach((spark, order) => {
      tl.set(spark, { x: origin.x, y: origin.y, opacity: 1, scale: 1, rotation: 0 }, burst)
      tl.to(
        spark,
        {
          physics2D: {
            velocity: 150 + ((order * 37) % 110),
            angle: 205 + ((order * 53) % 130),
            gravity: 520,
          },
          rotation: ((order % 2 ? 1 : -1) * (90 + order * 20)) % 360,
          opacity: 0,
          scale: 0.6,
          duration: 1,
          ease: 'none',
        },
        burst,
      )
    })
    tl.fromTo(q('output'), { opacity: 0.4 }, { opacity: 1, duration: 0.2 }, burst)
    scramble('output-text', value, { at: burst, duration: 0.8, chars })
  }

  step(0)
  select(ROLLS[0].tab)
  roll(0)

  ROLLS.slice(1).forEach((rollItem, offset) => {
    step(offset + 1, '+=0.65')
    select(rollItem.tab)
    roll(offset + 1)
  })

  cursorOut('+=0.5')
  final()
  wait(1.2)
}

function NumberBox({ value, className }: { value: number; className?: string }) {
  return (
    <span
      className={`flex h-7 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[11px] text-ink ${className ?? 'w-24'}`}
    >
      {value}
    </span>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Random Generator rolling a number between 1 and 100, then a random string, a UUID and a NanoID"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div
            data-d="tabs"
            className="relative flex w-fit rounded-lg border border-line bg-white/[0.03] p-0.5"
          >
            <span
              data-d="tab-pill"
              className="absolute inset-y-0.5 left-0.5 w-12 rounded-md bg-white/10"
            />
            {TABS.map((label, index) => (
              <span
                key={label}
                data-d={`tab-${index}`}
                className="relative px-2.5 py-1 text-[10.5px]"
                style={{ color: index === DEFAULT_TAB ? INK : DIM }}
              >
                {label}
              </span>
            ))}
          </div>
          <div className="relative h-7">
            <div data-d="range" className="absolute inset-0 flex items-center gap-2 opacity-0">
              <NumberBox value={MIN} />
              <span className="text-[11px] text-muted">–</span>
              <NumberBox value={MAX} />
            </div>
            <label
              data-d="length"
              className="absolute inset-0 flex items-center gap-2 text-[10.5px] text-ink-soft"
            >
              Length <NumberBox value={LENGTH} className="w-20" />
            </label>
          </div>
          <span
            data-d="generate"
            className="flex h-7 w-fit items-center gap-1.5 rounded-md bg-[var(--accent)] px-3 text-[11px] font-medium text-canvas"
          >
            <span data-d="dice" className="flex">
              <DicesIcon className="size-3.5" />
            </span>
            Generate
          </span>
          <div
            data-d="output"
            className="flex items-center justify-between gap-2 rounded border border-line bg-white/[0.03] px-2 py-1.5 opacity-0"
          >
            <code
              data-d="output-text"
              className="min-w-0 flex-1 break-all font-mono text-[12px] text-ink"
            />
            <span className="flex gap-1.5 text-muted">
              <CopyIcon className="size-3" />
              <SaveIcon className="size-3" />
              <XIcon className="size-3" />
            </span>
          </div>
        </div>
      </PanelChrome>
      {SPARKS.map((char, index) => (
        <span
          key={index}
          data-d="spark"
          className="pointer-events-none absolute left-0 top-0 z-20 font-mono text-[11px] font-semibold opacity-0"
          style={{ color: index % 3 ? 'var(--accent)' : '#f5f5f7' }}
        >
          {char}
        </span>
      ))}
    </DemoStage>
  )
}
